# ---------------------------------------------------------------- 서남 비상계단참(로비 흙벽을 판 길) · 탐험가 유해
text 2 16 "비상계단참. 벽에 층 번호가 페인트로 4, 5, 6… 위로 갈수록 흙이 짙다. 계단은 22층까지 — 같은 층이 열여덟 번 되풀이된다." w=3
prop remains 4 21
box 4 21 bag name="탐험가 유해 — 배낭" cond="KT_EXPL < 2"
text 5 21 "벽에 기대앉은 유해. 등산 배낭 · 개미산에 녹은 장화." scene=KT_EXPL
text 1 19 "아래로 — 로비 흙벽을 뚫은 굴." scene=KT_DOWN
# ---------------------------------------------------------------- 분양 홍보관(2077 '금빛 빌딩 — 전 세대 완판')
prop w_quote_kt 6 1
text 7 2 "분양 시세판. 층마다 분양가 줄 — 맨 위 60층은 숫자 대신 '완판'. 누가 손톱으로 숫자를 긁었다." w=3
prop model_kt 10 6 cond="KT_QUEEN == 0"
prop model_kt 10 6 state=ant cond="KT_QUEEN == 1"
text 10 8 "금박 분양 모형. 유리 상자 안 60층 탑 — 금박이 군데군데 뜯겨 나갔다. 개미가 금박을 굴로 날라 갔다." w=2
prop sales_booth_kt 3 4
text 3 5 "분양 상담 부스. 팸플릿 '하늘과 가장 가까운 주소 — 입주 2077년 11월'." w=2
prop sales_booth_kt 15 4
text 15 5 "상담 의자 위에 계약서 묶음. 서명란이 비었다. 날짜 '2077. 10. 23.'" w=2
box 15 4 desk name="상담 부스 서랍"
prop wait_chairs 3 10
prop plant_pot 1 3
prop plant_pot 20 3
prop w_hose_kt 12 1 cond="KT_HOSE3 == 0"
prop w_hose_kt 12 1 state=open cond="KT_HOSE3 == 1"
