prop w_cargo_kt 18 1 state=live cond="KT_POWER == 2"
prop w_cargo_kt 18 1 cond="KT_POWER != 2"
text 19 2 "화물 승강기 — 4층." scene=KT_CARGO3 w=2
# ---------------------------------------------------------------- 사무실(개미가 칸막이를 뜯어 굴 재료로)
prop cubicle_kt 24 4
prop cubicle_kt 28 4 state=ant
prop cubicle_kt 32 4
prop cubicle_kt 36 4 state=ant
prop cubicle_kt 24 9
prop cubicle_kt 36 9
prop office_desk 31 10
box 31 10 desk name="사무 책상 서랍"
prop ant_hole_kt 29 9
text 29 9 "바닥을 뚫은 개미 굴. 아래층에서 사각사각. 굴 둘레 흙이 반짝인다 — 여기서도 줄이 나와 위로 간다." w=2
prop w_memo_kt 26 1
text 27 2 "코르크 게시판. '10/23 23:00 전 직원 퇴근 — 분양 축하 회식 31층'. 귀퉁이가 큰턱에 찢겼다." w=2
prop w_glass_kt 43 1 state=broken cond="KT_GOND == 2"
prop w_glass_kt 43 1 cond="KT_GOND != 2"
text 44 2 "동쪽 통유리(20층). 바깥은 강바람." scene=KT_WIN3 cond="KT_GOND != 2"
text 44 2 "깨진 통유리. 바깥에 기운 곤돌라가 쇠줄 하나에 매달려 흔들린다." scene=KT_WIN3 cond="KT_GOND == 2"
text 44 3 "동북 비상계단. 위로 22층 — 흙 냄새가 진하다. 계단을 오르내리는 사각사각 소리." w=3
# ---------------------------------------------------------------- 12층 어린이 과학관 임시 전시(과학관 층이 사무층으로 옮겨 온 판)
prop exhibit_kt 10 18 state=empty
text 10 19 "어린이 과학관 임시 전시 '미래의 무기 — 광선총의 원리'. 유리 반구 아래 장난감 광선총. 옆 책 받침이 비었다 — 명판 '12층 과학관 문고'." w=2
prop display_case 15 18
text 15 19 "진열장. 진공관 모형 · '원자력 가정 시대' 그림책 · 어린이 우주복 헬멧." w=2
box 15 18 cabinet name="과학관 진열장"
prop kid_desk 18 21
text 18 21 "어린이 실험 탁자. 크레파스 그림 — 금빛 탑 꼭대기에 불 하나."
# ---------------------------------------------------------------- 위성 육아방(알 나르는 줄 — 22층과 이어짐)
prop egg_mound_kt 26 18
text 27 20 "위성 육아방의 알 무더기. 젖빛 알 · 끈적한 점액에서 시큼 달큰한 냄새." w=1 scene=KT_NURSE cond="KT_QUEEN == 0"
